// #c31690 (6a993d7b083193c466c31690) «הזמנת משתמש נוסף לחשבון העסקי» — менеджер testim приглашает участника:
// форма «הזמנת משתמש», проверка пустых полей, «ההזמנה נשלחה», строка «ממתין להצטרפות · בתוקף עד …», затем отмена (очистка).
// spec: specs/business-lifecycle.md (раздел 9) · кейс BIZ-INV-010 · seed: tests/seed.business.spec.ts (в файле storageState auth/business.json).
// Адрес — тестовый приёмник Resend delivered+<метка>@resend.dev: письмо считается доставленным, реальному человеку не уходит
// (адрес @example.com даёт send_failed — «ההזמנה נוצרה, אבל המייל לא נשלח», это другой сценарий, BIZ-INV-001).
// Вступление по ссылке (пароль), письмо в ящике и «פעיל» — вручную, BIZ-INV-011.
// @data: создаёт и отменяет приглашение QA-AUTO-c31690-<stamp> в общем бизнесе testim.
import * as path from 'path';
import { test, expect, Page } from '@playwright/test';

test.use({ storageState: path.resolve(__dirname, '../../../auth/business.json') });

const HASH = '#c31690 #6a993d7b083193c466c31690';

async function cancelInvitation(page: Page, name: string) {
  // Очистка: отменить созданное приглашение (меню строки; у строки со сбоем отправки — кнопка в строке).
  const row = page.getByTestId('user-row').filter({ hasText: name });
  if ((await row.count()) === 0) return;
  const menu = page.getByRole('button', { name: `פעולות עבור ההזמנה של ${name}` });
  if (await menu.isVisible()) {
    await menu.click();
    const item = page.getByRole('menuitem', { name: 'ביטול ההזמנה' });
    if (await item.isVisible()) await item.click();
    else await page.keyboard.press('Escape');
  }
  const confirm = page.getByRole('button', { name: 'ביטול ההזמנה', exact: true });
  if (!(await confirm.isVisible())) {
    await row.getByRole('button', { name: `ביטול ההזמנה של ${name}` }).click();
  }
  await confirm.click();
  await expect(page.getByText('ההזמנה בוטלה', { exact: true })).toBeVisible();
  await expect(row.filter({ hasText: 'ממתין להצטרפות' })).toHaveCount(0);
}

test.describe(`Пользователи и приглашения — приглашение участника менеджером (${HASH})`, () => {
  test(`business: форма «הזמנת משתמש» → «ההזמנה נשלחה», строка «ממתין להצטרפות · בתוקף עד …», отмена @desktop @data ${HASH}`, async ({ page }) => {
    const stamp = `${Date.now()}`;
    const name = `QA-AUTO-c31690-${stamp}`;
    const email = `delivered+qa-auto-c31690-${stamp}@resend.dev`;

    await page.goto('/settings/users');
    await page.getByRole('button', { name: 'הזמנת משתמש' }).click();

    const dialog = page.getByTestId('invite-user-dialog');
    await expect(dialog).toBeVisible();
    // Окно (AC1, треб.1; Figma 768:2176).
    await expect(dialog).toContainText('הזמנת משתמש');
    await expect(dialog).toContainText('נשלח מייל עם קישור אישי להצטרפות לחשבון של');
    const fullName = dialog.getByLabel('שם מלא');
    const mail = dialog.getByLabel('מייל', { exact: true });
    await expect(fullName).toBeVisible();
    await expect(mail).toBeVisible();
    const recruiter = dialog.getByRole('radio', { name: 'מנהל/ת מגייס/ת' });
    const manager = dialog.getByRole('radio', { name: 'מנהל/ת חשבון' });
    await expect(recruiter).toBeChecked(); // по умолчанию — מנהל/ת מגייס/ת
    await expect(manager).not.toBeChecked();
    await expect(dialog).toContainText('רואה רק את הסימולציות שתסמנו כאן ואת המועמדים שלהן.');
    const assign = dialog.getByRole('group', { name: 'שיוך לסימולציות' });
    await expect(assign).toBeVisible();
    // Срок — 7 дней, одноразовая (F-08 AC4, легенда «קישור אישי לשימוש אחד, בתוקף 7 ימים»).
    await expect(dialog.getByTestId('invite-validity')).toHaveText(/^ההזמנה בתוקף 7 ימים — עד .*\d.* — ולשימוש אחד$/);

    // Пустые поля — сообщения у полей, запрос не уходит.
    let invokeCalls = 0;
    page.on('request', (r) => {
      if (r.method() === 'POST' && /\/functions\/v1\/invite-user/.test(r.url())) invokeCalls += 1;
    });
    await dialog.getByRole('button', { name: 'שליחת הזמנה' }).click();
    await expect(dialog.getByText('יש להזין שם מלא')).toBeVisible();
    await expect(dialog.getByText('יש להזין כתובת מייל')).toBeVisible();
    expect(invokeCalls, 'invite-user не должен вызываться с пустыми полями').toBe(0);

    // מנהל/ת חשבון — без шиуха к симуляциям.
    await manager.check();
    await expect(assign).toHaveCount(0);
    await expect(dialog).toContainText('ולכן אין צורך לשייך סימולציות.');
    await recruiter.check();
    await expect(assign).toBeVisible();

    await fullName.fill(name);
    await mail.fill(email);
    const sims = assign.getByRole('checkbox');
    let simName: string | null = null;
    if ((await sims.count()) > 0) {
      await sims.first().check();
      const labelId = (await sims.first().getAttribute('aria-labelledby')) ?? '';
      simName = labelId ? ((await page.locator(`[id="${labelId}"]`).textContent()) ?? '').trim() : null;
    } else {
      await expect(assign).toContainText('עדיין אין בעסק סימולציות לשיוך.');
    }

    try {
      const respP = page.waitForResponse((r) => r.request().method() === 'POST' && /\/functions\/v1\/invite-user/.test(r.url()));
      await dialog.getByRole('button', { name: 'שליחת הזמנה' }).click();
      const resp = await respP;
      expect(resp.status(), 'invite-user').toBe(200);
      const body = await resp.json();
      // AC1: «נוצרת הזמנה בסטטוס ממתינה ונשלח מייל הזמנה».
      expect(body?.invitation?.delivery_status, 'delivery_status').toBe('sent');

      await expect(dialog).toBeHidden();
      await expect(page.getByText('ההזמנה נשלחה', { exact: true })).toBeVisible();
      const banner = page.getByText(`${name} יקבל/תקבל במייל`);
      await expect(banner).toBeVisible();
      await expect(banner).toContainText(email);
      await expect(banner).toContainText('קישור הצטרפות אישי. ההזמנה מופיעה ברשימה בסטטוס ממתינה עד להצטרפות.');

      // Строка списка: «ממתין להצטרפות», «בתוקף עד …», роль и шиух (треб.4, Figma 761:1904).
      const row = page.getByTestId('user-row').filter({ hasText: name });
      await expect(row).toHaveCount(1);
      await expect(row).toContainText('ממתין להצטרפות');
      await expect(row).toContainText(/בתוקף עד\s*\S*\d/);
      await expect(row).toContainText('מנהל/ת מגייס/ת');
      await expect(row).toContainText(simName || 'ללא שיוך');
      await expect(row).not.toContainText('שליחת המייל נכשלה');
    } finally {
      await cancelInvitation(page, name);
    }
  });
});
